#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	mediump float _Opacity;
uniform 	mediump float _UseDissolveTex;
uniform 	mediump float _DissolveIntensity;
uniform 	mediump float _BorderWidth;
uniform 	mediump vec4 _MainColor;
UNITY_LOCATION(0) uniform mediump sampler2D _MainTex;
UNITY_LOCATION(1) uniform mediump sampler2D _DissolveTex;
in mediump vec4 vs_COLOR0;
in highp vec4 vs_TEXCOORD0;
layout(location = 0) out highp vec4 SV_Target0;
mediump float u_xlat16_0;
mediump vec4 u_xlat16_1;
mediump vec3 u_xlat16_2;
bool u_xlatb3;
mediump float u_xlat16_4;
void main()
{
    u_xlat16_0 = _DissolveIntensity + 0.5;
    u_xlat16_0 = roundEven(u_xlat16_0);
    u_xlat16_0 = (-u_xlat16_0) + 1.0;
    u_xlat16_1.x = texture(_DissolveTex, vs_TEXCOORD0.zw).x;
    u_xlat16_4 = u_xlat16_1.x + (-_DissolveIntensity);
    u_xlat16_0 = _BorderWidth * u_xlat16_0 + u_xlat16_4;
    u_xlat16_0 = u_xlat16_0 / _BorderWidth;
    u_xlat16_0 = clamp(u_xlat16_0, 0.0, 1.0);
    u_xlat16_1 = texture(_MainTex, vs_TEXCOORD0.xy);
    u_xlat16_4 = u_xlat16_1.w * _MainColor.w;
    u_xlat16_2.xyz = u_xlat16_1.xyz + u_xlat16_1.xyz;
    u_xlat16_1.xyz = u_xlat16_2.xyz * vs_COLOR0.xyz;
    u_xlat16_4 = u_xlat16_4 * vs_COLOR0.w;
    u_xlat16_4 = u_xlat16_4 * _Opacity;
    u_xlat16_0 = u_xlat16_0 * u_xlat16_4 + (-u_xlat16_4);
    u_xlat16_1.w = _UseDissolveTex * u_xlat16_0 + u_xlat16_4;
    u_xlat16_1.w = clamp(u_xlat16_1.w, 0.0, 1.0);
    u_xlat16_0 = u_xlat16_1.w + -0.00100000005;
    SV_Target0 = u_xlat16_1;
    u_xlatb3 = u_xlat16_0<0.0;
    if(u_xlatb3){discard;}
    return;
}

