#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 _Time;
uniform 	vec4 _BaseTex_ST;
uniform 	float _BaseTex_SpeedU;
uniform 	float _BaseTex_SpeedV;
uniform 	mediump vec4 _Color;
uniform 	mediump float _RgbCtrl;
uniform 	mediump float _BaseTex_Channel;
uniform 	mediump float _Intensity;
uniform 	mediump float _ClampV;
uniform 	mediump float _Distortion;
uniform 	vec4 _Distortion_Tex_ST;
uniform 	mediump float _Distortion_IntensityU;
uniform 	mediump float _Distortion_IntensityV;
uniform 	mediump float _Distortion_Dir;
uniform 	float _Distortion_SpeedU;
uniform 	float _Distortion_SpeedV;
uniform 	mediump float _Dissolve;
uniform 	vec4 _Dissolve1_Tex_ST;
uniform 	mediump float _Dissolve1_Threshold;
uniform 	mediump float _Dissolve1_Smoothness;
uniform 	mediump float _Dissolve1_Invert;
uniform 	mediump float _Dissolve1_Distortion;
uniform 	vec4 _Dissolve2_Tex_ST;
uniform 	mediump float _Dissolve2_Threshold;
uniform 	mediump float _Dissolve2_Smoothness;
uniform 	mediump float _Dissolve2_Invert;
uniform 	mediump float _Dissolve2_Distortion;
uniform 	vec4 _Dissolve_Speed;
uniform 	mediump float _Mask;
uniform 	vec4 _Mask_Tex_ST;
uniform 	mediump float _Mask_Invert;
UNITY_LOCATION(0) uniform mediump sampler2D _Distortion_Tex;
UNITY_LOCATION(1) uniform mediump sampler2D _MainTex;
UNITY_LOCATION(2) uniform mediump sampler2D _BaseTex;
UNITY_LOCATION(3) uniform mediump sampler2D _Dissolve1_Tex;
UNITY_LOCATION(4) uniform mediump sampler2D _Dissolve2_Tex;
UNITY_LOCATION(5) uniform mediump sampler2D _Mask_Tex;
in highp vec2 vs_TEXCOORD0;
in highp vec4 vs_TEXCOORD1;
layout(location = 0) out mediump vec4 SV_Target0;
vec4 u_xlat0;
mediump vec3 u_xlat16_0;
bvec2 u_xlatb0;
vec4 u_xlat1;
mediump vec4 u_xlat16_1;
vec4 u_xlat2;
mediump vec2 u_xlat16_2;
mediump vec3 u_xlat16_3;
mediump vec3 u_xlat16_4;
float u_xlat5;
bool u_xlatb5;
mediump vec3 u_xlat16_8;
vec2 u_xlat10;
bool u_xlatb10;
mediump float u_xlat16_13;
float u_xlat15;
void main()
{
    u_xlatb0.xy = lessThan(vec4(0.0, 0.0, 0.0, 0.0), vec4(_Distortion, _ClampV, _Distortion, _Distortion)).xy;
    if(u_xlatb0.x){
        u_xlat0.xz = _Time.yy * vec2(_Distortion_SpeedU, _Distortion_SpeedV);
        u_xlat0.xz = vs_TEXCOORD0.xy * _Distortion_Tex_ST.xy + u_xlat0.xz;
        u_xlat0.xz = u_xlat0.xz + _Distortion_Tex_ST.zw;
        u_xlat0.x = texture(_Distortion_Tex, u_xlat0.xz).x;
        u_xlatb10 = _Distortion_Dir==1.0;
        u_xlat15 = u_xlat0.x * 2.0 + -1.0;
        u_xlat0.x = (u_xlatb10) ? u_xlat15 : u_xlat0.x;
        u_xlat10.x = u_xlat0.x * vs_TEXCOORD1.x + (-u_xlat0.x);
        u_xlat0.x = _RgbCtrl * u_xlat10.x + u_xlat0.x;
        u_xlat10.xy = vec2(_Distortion_IntensityU, _Distortion_IntensityV) * u_xlat0.xx + vs_TEXCOORD0.xy;
    } else {
        u_xlat10.xy = vs_TEXCOORD0.xy;
        u_xlat0.x = 0.0;
    }
    u_xlat10.xy = u_xlat10.xy * _BaseTex_ST.xy + _BaseTex_ST.zw;
    u_xlat1.xy = vec2(_BaseTex_SpeedU, _BaseTex_SpeedV) * _Time.yy + u_xlat10.xy;
    u_xlat10.x = u_xlat1.y;
    u_xlat10.x = clamp(u_xlat10.x, 0.0, 1.0);
    u_xlat1.z = (u_xlatb0.y) ? u_xlat10.x : u_xlat1.y;
    u_xlat2 = texture(_MainTex, u_xlat1.xz);
    u_xlat1 = texture(_BaseTex, u_xlat1.xz);
    u_xlatb5 = _BaseTex_Channel==1.0;
    u_xlat16_3.xyz = (bool(u_xlatb5)) ? u_xlat2.xxx : u_xlat2.yzw;
    u_xlat16_4.xyz = (bool(u_xlatb5)) ? u_xlat1.xxx : u_xlat1.yzw;
    u_xlat16_1.x = u_xlat1.x * u_xlat2.x;
    u_xlat16_1.yzw = u_xlat16_3.xyz * u_xlat16_4.xyz;
    u_xlat5 = u_xlat16_1.w * vs_TEXCOORD1.w;
    u_xlatb10 = 0.0<_Dissolve;
    if(u_xlatb10){
        u_xlatb10 = 0.0<_Dissolve1_Distortion;
        u_xlat0.xw = vec2(_Distortion_IntensityU, _Distortion_IntensityV) * u_xlat0.xx + vs_TEXCOORD0.xy;
        u_xlat2.xy = (bool(u_xlatb10)) ? u_xlat0.xw : vs_TEXCOORD0.xy;
        u_xlat2.xy = u_xlat2.xy * _Dissolve1_Tex_ST.xy + _Dissolve1_Tex_ST.zw;
        u_xlat2.xy = _Dissolve_Speed.xy * _Time.yy + u_xlat2.xy;
        u_xlat16_2.xy = texture(_Dissolve1_Tex, u_xlat2.xy).xw;
        u_xlat16_3.x = u_xlat16_2.y * u_xlat16_2.x;
        u_xlat16_8.x = u_xlat16_3.x * -2.0 + 1.0;
        u_xlat16_3.x = _Dissolve1_Invert * u_xlat16_8.x + u_xlat16_3.x;
        u_xlat2.xy = vs_TEXCOORD1.yz * vec2(2.0, 2.0) + vec2(-1.0, -1.0);
        u_xlat10.x = u_xlat2.x + (-_Dissolve1_Threshold);
        u_xlat10.x = _RgbCtrl * u_xlat10.x + _Dissolve1_Threshold;
        u_xlat16_3.x = (-u_xlat10.x) + u_xlat16_3.x;
        u_xlat16_8.x = float(1.0) / _Dissolve1_Smoothness;
        u_xlat16_3.x = u_xlat16_8.x * u_xlat16_3.x;
        u_xlat16_3.x = clamp(u_xlat16_3.x, 0.0, 1.0);
        u_xlat16_8.x = u_xlat16_3.x * -2.0 + 3.0;
        u_xlat16_3.x = u_xlat16_3.x * u_xlat16_3.x;
        u_xlat16_3.x = u_xlat16_3.x * u_xlat16_8.x;
        u_xlatb10 = 0.0<_Dissolve2_Distortion;
        u_xlat0.xz = (bool(u_xlatb10)) ? u_xlat0.xw : vs_TEXCOORD0.xy;
        u_xlat0.xz = u_xlat0.xz * _Dissolve2_Tex_ST.xy + _Dissolve2_Tex_ST.zw;
        u_xlat0.xz = _Dissolve_Speed.zw * _Time.yy + u_xlat0.xz;
        u_xlat16_0.xz = texture(_Dissolve2_Tex, u_xlat0.xz).xw;
        u_xlat16_8.x = u_xlat16_0.z * u_xlat16_0.x;
        u_xlat16_13 = u_xlat16_8.x * -2.0 + 1.0;
        u_xlat16_8.x = _Dissolve2_Invert * u_xlat16_13 + u_xlat16_8.x;
        u_xlat0.x = u_xlat2.y + (-_Dissolve2_Threshold);
        u_xlat0.x = _RgbCtrl * u_xlat0.x + _Dissolve2_Threshold;
        u_xlat16_8.x = (-u_xlat0.x) + u_xlat16_8.x;
        u_xlat16_13 = float(1.0) / _Dissolve2_Smoothness;
        u_xlat16_8.x = u_xlat16_13 * u_xlat16_8.x;
        u_xlat16_8.x = clamp(u_xlat16_8.x, 0.0, 1.0);
        u_xlat16_13 = u_xlat16_8.x * -2.0 + 3.0;
        u_xlat16_8.x = u_xlat16_8.x * u_xlat16_8.x;
        u_xlat16_8.x = u_xlat16_8.x * u_xlat16_13;
        u_xlat16_3.x = u_xlat5 * u_xlat16_3.x;
        u_xlat16_3.x = u_xlat16_8.x * u_xlat16_3.x;
    } else {
        u_xlat16_3.x = u_xlat5;
    }
    u_xlatb0.x = 0.0<_Mask;
    if(u_xlatb0.x){
        u_xlat0.xy = vs_TEXCOORD0.xy * _Mask_Tex_ST.xy + _Mask_Tex_ST.zw;
        u_xlat16_0.x = texture(_Mask_Tex, u_xlat0.xy).w;
        u_xlat16_8.x = u_xlat16_0.x * -2.0 + 1.0;
        u_xlat16_8.x = _Mask_Invert * u_xlat16_8.x + u_xlat16_0.x;
        u_xlat16_3.x = u_xlat16_8.x * u_xlat16_3.x;
    }
    u_xlat16_8.xyz = u_xlat16_1.xyz * _Color.xyz;
    u_xlat0.xyz = (-vs_TEXCOORD1.xyz) + vec3(1.0, 1.0, 1.0);
    u_xlat0.xyz = vec3(_RgbCtrl) * u_xlat0.xyz + vs_TEXCOORD1.xyz;
    u_xlat0.xyz = u_xlat0.xyz * u_xlat16_8.xyz;
    SV_Target0.xyz = u_xlat0.xyz * vec3(_Intensity);
    SV_Target0.w = u_xlat16_3.x * _Intensity;
    return;
}

